// Entry point: the generated page server (worker.js) wrapped with Sentry.
// worker.js is regenerated by publish_pages.py; keep hand-written code here.

import * as Sentry from '@sentry/cloudflare';
import generated from '../worker.js';
import { sentryOptions } from './sentry.js';

export interface Env {
  SENTRY_DSN?: string;
}

// Uncaught errors reach Sentry when SENTRY_DSN is set (errors only; see src/sentry.ts).
export default Sentry.withSentry((env: Env) => sentryOptions(env), {
  fetch(request: Request): Promise<Response> {
    return generated.fetch(request);
  },
});
